+const instances: any[] = [];
+jest.mock('ws', () => {
+  const Mock: any = jest.fn().mockImplementation((url: string, opts: any) => {
+    const handlers: Record<string, (...a: any[]) => void> = {};
+    const inst = {
+      url,
+      opts,
+      handlers,
+      sent: [] as string[],
+      readyState: 1,
+      on: (e: string, cb: any) => {
+        handlers[e] = cb;
+      },
+      send: (s: string) => inst.sent.push(s),
+      close: jest.fn(),
+    };
+    instances.push(inst);
+    return inst;
+  });
+  Mock.OPEN = 1;
+  return { __esModule: true, default: Mock };
+});
+
+import {
+  OPENAI_REALTIME_URL,
+  RealtimeVoiceService,
+} from './realtime-voice.service';
+
+describe('RealtimeVoiceService (GA)', () => {
+  it('uses gpt-realtime-2.1, no beta header, GA events', async () => {
+    expect(OPENAI_REALTIME_URL).toContain('model=gpt-realtime-2.1');
+    const svc = new RealtimeVoiceService('k');
+    const audio = jest.fn();
+    const p = svc.connectToOpenAI(audio);
+    const ws = instances[0];
+    expect(ws.opts.headers['OpenAI-Beta']).toBeUndefined();
+    ws.handlers.open();
+    await p;
+    const session = JSON.parse(ws.sent[0]).session;
+    expect(session.type).toBe('realtime');
+    expect(session.audio.output.voice).toBe('alloy');
+    ws.handlers.message(
+      Buffer.from(JSON.stringify({ type: 'response.output_audio.delta', delta: 'x' })),
+    );
+    expect(audio).toHaveBeenCalledWith('x');
+  });
+});
