@@ -0,0 +1,23 @@
+import OpenAI from 'openai';
+import * as fs from 'fs';
+
+describe('openai v7', () => {
+  it('is 7.x and runtime is Node >=22', () => {
+    const v = JSON.parse(fs.readFileSync('node_modules/openai/package.json', 'utf8')).version;
+    expect(v.startsWith('7.')).toBe(true);
+    expect(parseInt(process.versions.node, 10)).toBeGreaterThanOrEqual(22);
+  });
+  it('chat.completions.create sends expected body', async () => {
+    let body: any;
+    const client = new OpenAI({
+      apiKey: 'x',
+      fetch: (async (_u: any, init: any) => {
+        body = JSON.parse(init.body);
+        return new Response(JSON.stringify({ id: '1', object: 'chat.completion', choices: [] }), { headers: { 'content-type': 'application/json' } });
+      }) as any,
+    });
+    await client.chat.completions.create({ model: 'gpt-4o-mini', messages: [{ role: 'user', content: 'hi' }], max_tokens: 5 });
+    expect(body.model).toBe('gpt-4o-mini');
+    expect(body.max_tokens).toBe(5);
+  });
+});

