+  return fs.readdirSync(d, { withFileTypes: true }).flatMap((e) =>
+    e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)],
+  );
+}
+
+describe('retired OpenAI models', () => {
+  const files = walk(path.join(__dirname, '..')).filter(
+    (f) => f.endsWith('.ts') && !f.endsWith('.spec.ts') && !f.includes('realtime'),
+  );
+  it('no retired chat model defaults remain', () => {
+    const bad = files.filter((f) => /gpt-4o-mini|gpt-4\.1|'gpt-4o'/.test(fs.readFileSync(f, 'utf8')));
+    expect(bad).toEqual([]);
+  });
+  it('chat calls use max_completion_tokens', () => {
+    const bad = files.filter((f) => /\bmax_tokens\b/.test(fs.readFileSync(f, 'utf8')));
+    expect(bad).toEqual([]);
+  });
+});
