+import { RealtimeVoiceService, OPENAI_REALTIME_URL } from './realtime-voice.service';
+
+const instances: any[] = [];
+jest.mock('ws', () => {
+  const M: any = jest.fn().mockImplementation((url: string, opts: any) => {
+    const i: any = { url, opts, handlers: {}, sent: [] as string[] };
+    i.on = (e: string, h: any) => { i.handlers[e] = h; };
+    i.send = (m: string) => i.sent.push(m);
+    instances.push(i);
+    return i;
+  });
+  M.OPEN = 1;
+  return { __esModule: true, default: M };
+});
+
+describe('RealtimeVoiceService GA', () => {
+  it('uses GA model, no beta header, GA session and events', async () => {
+    expect(OPENAI_REALTIME_URL).toContain('model=gpt-realtime-2.1');
+    const svc = new RealtimeVoiceService('k');
+    const onAudio = jest.fn();
+    const p = svc.connectToOpenAI(onAudio);
+    const i = instances[0];
+    expect(i.opts.headers['OpenAI-Beta']).toBeUndefined();
+    i.handlers.open();
+    await p;
+    const s = JSON.parse(i.sent[0]).session;
+    expect(s.type).toBe('realtime');
+    expect(s.audio.output.voice).toBe('alloy');
+    i.handlers.message(Buffer.from(JSON.stringify({ type: 'response.output_audio.delta', delta: 'x' })));
+    expect(onAudio).toHaveBeenCalledWith('x');
+  });
+});
